class Node:
    def __init__(self, val):
        self.val = val
        self.next = None
class LinkedList:
    def __init__(self):
        self.head = None
    def append(self, v):
        n = Node(v)
        if self.head is None:
            self.head = n
            return
        cur = self.head
        while cur.next is not None:
            cur = cur.next
        cur.next = n
    def to_list(self):
        out = []
        cur = self.head
        while cur is not None:
            out.append(cur.val)
            cur = cur.next
        return out
    def length(self):
        cnt = 0
        cur = self.head
        while cur is not None:
            cnt += 1
            cur = cur.next
        return cnt
ll = LinkedList()
for v in [1, 2, 3, 4]:
    ll.append(v)
print(ll.to_list(), ll.length())
empty = LinkedList()
print(empty.to_list(), empty.length())

class TNode:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
class BST:
    def __init__(self):
        self.root = None
    def insert(self, key):
        if self.root is None:
            self.root = TNode(key)
            return
        cur = self.root
        while True:
            if key < cur.key:
                if cur.left is None:
                    cur.left = TNode(key)
                    return
                cur = cur.left
            else:
                if cur.right is None:
                    cur.right = TNode(key)
                    return
                cur = cur.right
    def inorder(self):
        out = []
        def walk(n):
            if n is None:
                return
            walk(n.left)
            out.append(n.key)
            walk(n.right)
        walk(self.root)
        return out
t = BST()
for k in [5, 3, 8, 1, 4, 7, 9]:
    t.insert(k)
print(t.inorder())

class Builder:
    def __init__(self):
        self.parts = []
    def add(self, s):
        self.parts.append(s)
        return self
    def upper(self):
        self.parts = [p.upper() for p in self.parts]
        return self
    def result(self):
        return ' '.join(self.parts)
